import{_ as t,o as h,c as a,a3 as i}from"./chunks/framework.DX_KL3e0.js";const o="/help/screenshots/ho-so-cua-toi/tong-quan.png",m=JSON.parse('{"title":"Hợp đồng & Hồ sơ","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/ho-so-cua-toi.md","filePath":"chuc-nang/ho-so-cua-toi.md","lastUpdated":1781595364000}'),c={name:"chuc-nang/ho-so-cua-toi.md"};function s(g,n,r,l,u,e){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="hop-đong-ho-so" tabindex="-1">Hợp đồng &amp; Hồ sơ <a class="header-anchor" href="#hop-đong-ho-so" aria-label="Permalink to &quot;Hợp đồng &amp; Hồ sơ&quot;">​</a></h1><p>Module <strong>Hợp Đồng &amp; Hồ Sơ</strong> (Hồ Sơ Của Tôi) là không gian tự phục vụ để mỗi nhân sự theo dõi hợp đồng lao động của mình và quản lý hồ sơ, giấy tờ cá nhân.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/ho-so-cua-toi</code> (menu <strong>Hợp Đồng &amp; Hồ Sơ</strong>, luôn hiện cho mọi người dùng).</li><li><strong>Ai dùng được:</strong> Tất cả nhân sự — mỗi người chỉ thấy hợp đồng và hồ sơ của chính mình.</li><li><strong>Gồm:</strong> Hợp đồng của tôi · Hồ sơ của tôi (tải lên, xem, tải xuống, yêu cầu đổi).</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+o+'" alt="Trang Hợp đồng &amp; Hồ sơ của tôi"></p><p>Trang gồm hai phần: <strong>Hợp đồng của tôi</strong> và <strong>Hồ sơ của tôi</strong>.</p><h2 id="_1-hop-đong-cua-toi" tabindex="-1">1. Hợp đồng của tôi <a class="header-anchor" href="#_1-hop-đong-cua-toi" aria-label="Permalink to &quot;1. Hợp đồng của tôi&quot;">​</a></h2><p>Hiển thị các hợp đồng lao động gắn với bạn dưới dạng thẻ, kèm <strong>nhãn hạn</strong> (sắp hết hạn / còn hiệu lực). Nếu chưa có hợp đồng nào, trang hiện thông báo &quot;Bạn chưa có hợp đồng nào trong hệ thống&quot; — khi đó hãy liên hệ Phòng Nhân Sự / C&amp;B.</p><h2 id="_2-ho-so-cua-toi" tabindex="-1">2. Hồ sơ của tôi <a class="header-anchor" href="#_2-ho-so-cua-toi" aria-label="Permalink to &quot;2. Hồ sơ của tôi&quot;">​</a></h2><p>Danh sách giấy tờ cá nhân (CCCD, bằng cấp, sơ yếu lý lịch...), mỗi mục hiển thị tên, loại hồ sơ, dung lượng và ngày tải lên.</p><h3 id="tai-len-ho-so-moi" tabindex="-1">Tải lên hồ sơ mới <a class="header-anchor" href="#tai-len-ho-so-moi" aria-label="Permalink to &quot;Tải lên hồ sơ mới&quot;">​</a></h3><ol><li>Bấm <strong>Tải lên</strong> ở góc phải mục <em>Hồ sơ của tôi</em>.</li><li>Trong cửa sổ hiện ra, chọn loại hồ sơ, đặt tiêu đề và chọn tệp.</li><li>Xác nhận để lưu — hồ sơ xuất hiện ngay trong danh sách.</li></ol><h3 id="xem-va-tai-xuong" tabindex="-1">Xem và tải xuống <a class="header-anchor" href="#xem-va-tai-xuong" aria-label="Permalink to &quot;Xem và tải xuống&quot;">​</a></h3><ul><li>Bấm biểu tượng <strong>con mắt</strong> để xem trước (PDF mở tab mới, ảnh hiển thị trong lightbox).</li><li>Bấm biểu tượng <strong>tải xuống</strong> để lưu tệp về máy.</li></ul><h3 id="yeu-cau-đoi-ho-so" tabindex="-1">Yêu cầu đổi hồ sơ <a class="header-anchor" href="#yeu-cau-đoi-ho-so" aria-label="Permalink to &quot;Yêu cầu đổi hồ sơ&quot;">​</a></h3><p>Bạn không xóa trực tiếp hồ sơ. Thay vào đó:</p><ol><li>Bấm biểu tượng <strong>bút chì</strong> (Yêu cầu đổi) trên hồ sơ cần thay.</li><li>Tải lên tệp mới trong cửa sổ yêu cầu.</li><li>Yêu cầu chuyển sang trạng thái <strong>Chờ duyệt</strong> — bộ phận C&amp;B sẽ xem xét và phê duyệt trước khi tệp được cập nhật.</li></ol><div class="info custom-block"><p class="custom-block-title">Vì sao phải qua duyệt?</p><p>Để giữ tính chính xác và lưu vết hồ sơ nhân sự, mọi thay đổi hồ sơ đều do C&amp;B xét duyệt thay vì sửa/xóa trực tiếp. Trong lúc chờ, mục hồ sơ hiển thị nhãn <strong>Chờ duyệt</strong>.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi có thấy hồ sơ của người khác không?</strong> Không. Trang chỉ hiển thị hợp đồng và hồ sơ của riêng bạn.</p><p><strong>Tôi tải nhầm tệp, làm sao thay?</strong> Dùng nút <strong>Yêu cầu đổi</strong> (biểu tượng bút chì) và tải tệp đúng lên; C&amp;B sẽ duyệt thay thế.</p><p><strong>Hợp đồng của tôi sắp hết hạn?</strong> Thẻ hợp đồng có nhãn hạn để bạn chủ động theo dõi. Liên hệ Phòng Nhân Sự nếu cần gia hạn.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tra-cuu.html">Tra cứu</a> · <a href="/help/chuc-nang/cham-cong.html">Dữ liệu Chấm công</a></p>',24)])])}const d=t(c,[["render",s]]);export{m as __pageData,d as default};
